export function episodicMemoryEvaluator(decisionBranches, historicalData) {
  const prioritizedBranches = decisionBranches.map(branch => {
    const score = historicalData[branch.id]?.successRate || 0;
    return { ...branch, priority: score };
  });

  return prioritizedBranches.sort((a, b) => b.priority - a.priority);
}